Read Sheet1, locate the Task and Responsibility columns by header text, and sort the data rows by those two columns with a stable sort. Write the resulting rows as plain values, converting date-like values to real datetimes, into both Sheet1 and Sheet2 A1:F14. Save the modified workbook to OUT.

```python
import shutil
import openpyxl
from datetime import datetime, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

NCOLS = 6
ANSWER_LAST_ROW = 14

def normalize_text(v):
    if isinstance(v, str):
        s = v.strip()
        return s if s != "" else None
    return v

src = vals["Sheet1"]

header = [normalize_text(src.cell(row=1, column=c).value) for c in range(1, NCOLS + 1)]

task_col = None
resp_col = None
date_cols = set()

for idx, h in enumerate(header, start=1):
    if h == "Task":
        task_col = idx
    elif h == "Responsibility":
        resp_col = idx
    if h and "Date" in str(h):
        date_cols.add(idx)

if task_col is None:
    task_col = 3
if resp_col is None:
    resp_col = 6

def prepare_value(col, v):
    v = normalize_text(v)
    if v is None:
        return None
    if isinstance(v, datetime):
        return v

    if col in date_cols:
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            if v == 0:
                return None
            return datetime(1899, 12, 30) + timedelta(days=float(v))

        if isinstance(v, str):
            try:
                f = float(v)
                if f == 0:
                    return None
                return datetime(1899, 12, 30) + timedelta(days=f)
            except ValueError:
                pass

            for fmt in (
                "%Y-%m-%d %H:%M:%S",
                "%Y-%m-%dT%H:%M:%S",
                "%Y-%m-%d",
                "%Y/%m/%d %H:%M:%S",
                "%Y/%m/%d",
                "%d/%m/%Y",
                "%m/%d/%Y",
            ):
                try:
                    return datetime.strptime(v, fmt)
                except ValueError:
                    pass

    return v

last_row = 1
for r in range(2, src.max_row + 1):
    if any(src.cell(row=r, column=c).value is not None for c in range(1, NCOLS + 1)):
        last_row = r

records = []
for r in range(2, last_row + 1):
    row = [prepare_value(c, src.cell(row=r, column=c).value) for c in range(1, NCOLS + 1)]
    task = row[task_col - 1]
    resp = row[resp_col - 1]
    key = (
        "" if task is None else str(task).strip(),
        "" if resp is None else str(resp).strip(),
        r,
    )
    records.append((key, row))

records.sort(key=lambda item: item[0])
sorted_rows = [row for _, row in records]

write_last = max(ANSWER_LAST_ROW, last_row)

for sheet_name in ("Sheet1", "Sheet2"):
    if sheet_name not in wb.sheetnames:
        ws = wb.create_sheet(sheet_name)
    else:
        ws = wb[sheet_name]

    for r in range(1, write_last + 1):
        for c in range(1, NCOLS + 1):
            ws.cell(row=r, column=c).value = None

    for c in range(1, NCOLS + 1):
        ws.cell(row=1, column=c).value = prepare_value(c, src.cell(row=1, column=c).value)

    for i, row in enumerate(sorted_rows, start=2):
        if i > write_last:
            break
        for c, v in enumerate(row, start=1):
            ws.cell(row=i, column=c).value = v

wb.save(OUT)

print("task_col", task_col, "resp_col", resp_col, "last_row", last_row, "rows", len(sorted_rows))
if sorted_rows:
    print("first", sorted_rows[0])
    print("last", sorted_rows[-1])
```

